"""Domain value object for an embedding vector."""

import math
from dataclasses import dataclass
from typing import Iterable


from ..errors import EmptyEmbeddingError, NonFiniteEmbeddingValueError


@dataclass(frozen=True, slots=True)
class Embedding:
    """Immutable vector generated by an embedding model."""

    vector: tuple[float, ...]

    def __post_init__(self) -> None:
        if not self.vector:
            raise EmptyEmbeddingError()

        if any(not math.isfinite(value) for value in self.vector):
            raise NonFiniteEmbeddingValueError()

    @classmethod
    def from_values(cls, values: Iterable[float]) -> "Embedding":
        """Create an immutable embedding from numeric values."""
        return cls(vector=tuple(float(value) for value in values))

    @property
    def dimension(self) -> int:
        """Return the vector dimension."""
        return len(self.vector)
